import java.util.ArrayDeque;
import java.util.Deque;

public class OperacionesPila {
    public int sumarElementos(Deque<Integer> pila) {
        int suma = 0;
        Deque<Integer> pilaAuxiliar = new ArrayDeque<>();

        // 1. Vaciar la pila original, sumar los valores y guardarlos en la auxiliar
        while (!pila.isEmpty()) {
            int elemento = pila.pop();
            suma += elemento;
            pilaAuxiliar.push(elemento);
        }

        // 2. Restaurar los elementos de vuelta a la pila original
        while (!pilaAuxiliar.isEmpty()) {
            pila.push(pilaAuxiliar.pop());
        }

        return suma;
    }
}

